function requestRender(){if(active&&!raf)raf=requestAnimationFrame(render);}
function resize(){if(!renderer||!active)return;let w=root.clientWidth,h=root.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();requestRender();}
function updatePhotos(){if(ready)updateWorldPhoto(station);const s=stops[station];q('#stationName').textContent=s.name;q('#stationSubtitle').textContent=s.note;q('#stationNumber').textContent=String(station+1).padStart(2,'0')+' / 03';q('#hotspotTitle').textContent=PHOTOS[s.selected].title;q('#stationThumbs').replaceChildren();let list=s.photos.includes(s.selected)?s.photos:[s.selected,...s.photos.slice(0,2)];for(let i of list){let b=document.createElement('button');b.setAttribute('aria-label','此处照片：'+PHOTOS[i].title);b.setAttribute('aria-current',String(i===s.selected));b.innerHTML='<img alt="" src="'+PHOTOS[i].thumb+'">';b.onclick=()=>{s.selected=i;updatePhotos();show(i,{animate:false});};q('#stationThumbs').append(b);}document.querySelectorAll('[data-station]').forEach((b,i)=>b.setAttribute('aria-current',String(i===station)));}
function placeHotspot(){const hot=q('#sceneHotspot');if(photoOpen||photoBusy){hot.hidden=true;return;}const v=new THREE.Vector3(...stops[station].spot);if(worldPhotos[station])v.y-=worldPhotos[station].height/2+.35;const f=v.clone().sub(camera.position);if(f.dot(camera.getWorldDirection(new THREE.Vector3()))<=0){hot.hidden=true;return;}v.project(camera);hot.hidden=Math.abs(v.x)>.85||Math.abs(v.y)>.7;hot.style.left=((v.x+1)*.5*root.clientWidth)+'px';hot.style.top=((-v.y+1)*.5*root.clientHeight)+'px';}
function go(i,instant=false){if(photoBusy||photoOpen)return;station=i;const s=stops[i],a=homeAngles(s);if(instant){camera.position.set(...s.pos);yaw=targetYaw=a.yaw;pitchAngle=targetPitch=a.pitch;motion=null;}else moveTo(new THREE.Vector3(...s.pos),a.yaw,a.pitch);updatePhotos();show(s.selected,{animate:false});q('.stadium-intro').classList.add('quiet');requestRender();}
function enter(){if(active)return;configureStops();active=true;root.hidden=false;wakeControls();document.body.classList.add('exploring','stadium-mode');q('#previewMode').setAttribute('aria-pressed','false');q('#exploreMode').setAttribute('aria-pressed','true');pitch(false);q('#stadiumLoad').hidden=false;try{if(!ready)build();let i=stops.findIndex(s=>s.photos.includes(current));if(i<0)i=PHOTOS[current].category==='action'?1:2;stops[i].selected=current;go(i,true);q('.stadium-intro').classList.remove('quiet');q('#stadiumLoad').hidden=true;canvas.focus({preventScroll:true});resize();}catch(e){q('#stadiumLoad').hidden=true;q('#stadiumError').hidden=false;console.error('Stadium initialization:',e);}}
function leave(){if(photoBusy)return;if(document.fullscreenElement===root)document.exitFullscreen().catch(()=>{});if(photoOpen)closePhoto(true);active=false;root.hidden=true;document.body.classList.remove('exploring','stadium-mode');q('#previewMode').setAttribute('aria-pressed','true');q('#exploreMode').setAttribute('aria-pressed','false');cancelAnimationFrame(raf);raf=0;motion=null;fitPhoto();q('#exploreMode').focus();}
const worldPhotos=[],textureCache=new Map();
const photoLocations=[[-24,2,7],[-6.3,2,.8],[-8,3.05,-14]];
function getPhotoTexture(index){if(textureCache.has(index))return textureCache.get(index);const promise=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{const cap=Math.min(renderer.capabilities.maxTextureSize,innerWidth<600?2048:3072),scale=Math.min(1,cap/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());resolve(t);}catch(e){reject(e);}};im.onerror=()=>{textureCache.delete(index);reject(new Error('Original photograph could not load'));};im.src=src(PHOTOS[index]);});textureCache.set(index,promise);return promise;}
function buildPhotoWindows(){stops.forEach((s,i)=>{s.spot=photoLocations[i];const group=new THREE.Group();group.position.set(...photoLocations[i]);group.lookAt(new THREE.Vector3(s.pos[0],group.position.y,s.pos[2]));const mat=new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:0,toneMapped:false});mat.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>','#include <map_fragment>\n#ifdef USE_MAP\n float edgeDistance=min(min(vMapUv.x,1.0-vMapUv.x),min(vMapUv.y,1.0-vMapUv.y)); diffuseColor.a *= smoothstep(0.0,0.018,edgeDistance);\n#endif');};const art=new THREE.Mesh(new THREE.PlaneGeometry(1,1),mat);group.add(art);const rim=new THREE.Mesh(new THREE.BoxGeometry(1,1,.025),new THREE.MeshStandardMaterial({color:'#c0c9b1',metalness:.4,roughness:.6}));rim.position.z=-.021;rim.visible=false;group.add(rim);scene.add(group);const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=128;const sc=shadowCanvas.getContext('2d'),g=sc.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(0,0,0,.28)');g.addColorStop(1,'rgba(0,0,0,0)');sc.fillStyle=g;sc.fillRect(0,0,128,128);const sh=new THREE.Mesh(new THREE.PlaneGeometry(5.7,1.7),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));sh.rotation.x=-Math.PI/2;sh.position.set(group.position.x,.02,group.position.z);scene.add(sh);worldPhotos.push({group,art,rim,index:-1,width:4.8,height:3.2,token:0});});}
async function updateWorldPhoto(i){const o=worldPhotos[i];if(!o)return;const index=stops[i].selected;if(o.index===index)return;o.index=index;const p=PHOTOS[index],ratio=p.width/p.height;o.width=Math.min(4.8,3.2*ratio);o.height=o.width/ratio;o.art.scale.set(o.width,o.height,1);o.rim.scale.set(o.width+.025,o.height+.025,1);const token=++o.token;try{const tex=await getPhotoTexture(index);if(token!==o.token)return;o.art.material.map=tex;o.art.material.opacity=1;o.art.material.needsUpdate=true;prunePhotoTextures();}catch(e){console.error('Photograph texture:',e);}}
function prunePhotoTextures(){if(textureCache.size<=5)return;const used=new Set(worldPhotos.map(o=>o.index));for(const [key,promise]of textureCache){if(textureCache.size<=5)break;if(!used.has(key)){textureCache.delete(key);promise.then(t=>t.dispose());}}}
function showSceneImage(){updateWorldPhoto(station);const s=stops[station],p=PHOTOS[s.selected];q('#scenePhotoTitle').textContent=p.title+' / AP1';q('#scenePhoto').setAttribute('aria-label',p.title+' / AP1');let i=s.photos.indexOf(s.selected);q('#scenePhotoCount').textContent=(i<0?'精选':String(i+1).padStart(2,'0')+' / '+String(s.photos.length).padStart(2,'0'));}
async function openPhoto(){if(photoBusy||photoOpen||!ready)return;photoBusy=true;q('#viewHere').textContent='原图载入中…';storedFocus=document.activeElement;try{await getPhotoTexture(stops[station].selected);saved={pos:camera.position.clone(),yaw,pitch:pitchAngle};motion=null;const o=worldPhotos[station],center=o.group.position.clone(),normal=new THREE.Vector3(0,0,1).applyQuaternion(o.group.quaternion);const vfov=THREE.MathUtils.degToRad(camera.fov),distance=Math.max(o.width/(2*Math.tan(vfov/2)*camera.aspect*.74),o.height/(2*Math.tan(vfov/2)*.65));const end=center.clone().addScaledVector(normal,distance);end.y=1.68;const v=center.clone().sub(end),a=Math.atan2(v.x,v.z),p=Math.atan2(v.y,Math.hypot(v.x,v.z));q('#sceneHotspot').hidden=true;const finish=()=>{q('#viewHere').textContent='走近作品 ↗';showSceneImage();q('#scenePhoto').hidden=false;photoOpen=true;photoBusy=false;projectionBase=null;syncProjection();root.classList.add('viewing-photo');q('#returnToField').focus();};moveTo(end,a,p,1000,finish);}catch(e){photoBusy=false;q('#viewHere').textContent='重试查看 ↗';console.error(e);}}
function closePhoto(instant=false){if(!photoOpen)return;clearProjection();photoOpen=false;q('#scenePhoto').hidden=true;root.classList.remove('viewing-photo');if(saved){if(instant){camera.position.copy(saved.pos);yaw=targetYaw=saved.yaw;pitchAngle=targetPitch=saved.pitch;}else moveTo(saved.pos,saved.yaw,saved.pitch,700);}storedFocus?.focus({preventScroll:true});requestRender();}
function cycle(dir){clearProjection();const s=stops[station];let n=s.photos.indexOf(s.selected);s.selected=s.photos[(n+dir+s.photos.length)%s.photos.length];showSceneImage();updatePhotos();show(s.selected,{animate:false});syncProjection();}
q('#exploreMode').onclick=enter;q('#previewMode').onclick=leave;q('#backToPhotos').onclick=leave;q('#fallbackPreview').onclick=leave;q('#enterScenePhoto').onclick=openPhoto;q('#viewHere').onclick=openPhoto;q('#returnToField').onclick=()=>closePhoto();q('#scenePhotoPrev').onclick=()=>cycle(-1);q('#scenePhotoNext').onclick=()=>cycle(1);document.querySelectorAll('[data-station]').forEach((b,i)=>b.onclick=()=>go(i));q('#resetLook').onclick=()=>go(station);
q('#stadiumFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await root.requestFullscreen();}catch{q('#stadiumFullscreen').textContent='页面已铺满';}};
canvas.onpointerdown=e=>{if(photoBusy||(photoOpen&&!projectionLayer))return;motion=null;drag={x:e.clientX,y:e.clientY,yaw:targetYaw,pitch:targetPitch};canvas.setPointerCapture(e.pointerId);q('.stadium-intro').classList.add('quiet');};canvas.onpointermove=e=>{if(!drag)return;if(photoOpen&&projectionLayer&&projectionBase){const offset=THREE.MathUtils.clamp((e.clientX-drag.x)/root.clientWidth*.65,-.22,.22),right=new THREE.Vector3(Math.cos(projectionBase.yaw),0,-Math.sin(projectionBase.yaw));camera.position.copy(projectionBase.pos).addScaledVector(right,offset);const look=worldPhotos[station].group.position.clone().sub(camera.position);targetYaw=Math.atan2(look.x,look.z);targetPitch=Math.atan2(look.y,Math.hypot(look.x,look.z));return;}targetYaw=drag.yaw-(e.clientX-drag.x)*.003;targetPitch=Math.max(-.42,Math.min(.6,drag.pitch+(e.clientY-drag.y)*.002));};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;
// Capture exploration keys before the standard gallery handler; trap focus in the immersive photo view.
document.addEventListener('keydown',e=>{if(!active)return;if(photoOpen){if(['Escape','ArrowLeft','ArrowRight','Tab'].includes(e.key)){e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();closePhoto();}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cycle(e.key==='ArrowLeft'?-1:1);}else{const controls=[q('#returnToField'),...(!q('#projectionBar').hidden?[q('#projectionToggle')]:[]),q('#scenePhotoPrev'),q('#scenePhotoNext')];let i=controls.indexOf(document.activeElement),n=(i+(e.shiftKey?-1:1)+controls.length)%controls.length;e.preventDefault();controls[n].focus();}}return;}if(e.key==='Escape'){e.stopImmediatePropagation();e.preventDefault();leave();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.stopImmediatePropagation();e.preventDefault();if(e.key==='ArrowLeft')targetYaw+=.12;if(e.key==='ArrowRight')targetYaw-=.12;if(e.key==='ArrowUp')go((station+1)%3);if(e.key==='ArrowDown')go((station+2)%3);}},true);
new ResizeObserver(resize).observe(root);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else requestRender();});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);raf=0;q('#stadiumError').hidden=false;});

export function start(){enter();}

let idleTimer=0,lastWake=0,pinnedControls=false;
function wakeControls(){root.classList.remove('ui-resting');clearTimeout(idleTimer);if(!pinnedControls)idleTimer=setTimeout(()=>{if(active)root.classList.add('ui-resting');},4200);}
root.addEventListener('pointermove',()=>{if(performance.now()-lastWake>350){lastWake=performance.now();wakeControls();}},{passive:true});
root.addEventListener('pointerdown',wakeControls,{passive:true});root.addEventListener('keydown',wakeControls);
q('#tourControls').onclick=()=>{pinnedControls=!pinnedControls;q('#tourControls').setAttribute('aria-pressed',String(pinnedControls));wakeControls();};

let projectionLayer=null,projectionBase=null,projectionEnabled=true,projectionTicket=0;
function clearProjection(){projectionTicket++;projectionLayer?.dispose();projectionLayer=null;for(const o of worldPhotos)o.art.visible=true;q('#projectionBar').hidden=true;}
async function syncProjection(){const ticket=++projectionTicket;projectionLayer?.dispose();projectionLayer=null;for(const o of worldPhotos)o.art.visible=true;const applicable=photoOpen&&station===1&&stops[station].selected===0;q('#projectionBar').hidden=!applicable;if(!applicable)return;if(!projectionBase)projectionBase={pos:camera.position.clone(),yaw,pitch:pitchAngle};q('#projectionToggle').setAttribute('aria-pressed',String(projectionEnabled));q('#projectionToggle').textContent=projectionEnabled?'对比普通画面':'恢复透视接地';if(!projectionEnabled)return;try{const texture=await getPhotoTexture(0);if(ticket!==projectionTicket||!photoOpen||stops[station].selected!==0)return;projectionLayer=createGoalProjection(THREE,scene,worldPhotos[station],projectionBase.pos,texture);worldPhotos[station].art.visible=false;}catch(e){console.error('Goal projection study:',e);}}
q('#projectionToggle').onclick=()=>{projectionEnabled=!projectionEnabled;if(projectionBase){camera.position.copy(projectionBase.pos);yaw=targetYaw=projectionBase.yaw;pitchAngle=targetPitch=projectionBase.pitch;}syncProjection();};

function configureStops(){const match=PHOTOS[current].match;const entries=PHOTOS.map((p,i)=>({p,i})).filter(x=>x.p.match===match),actions=entries.filter(x=>x.p.category==='action').map(x=>x.i),sides=entries.filter(x=>x.p.category==='sideline').map(x=>x.i),human=entries.filter(x=>['stands','story'].includes(x.p.category)).map(x=>x.i);const split=Math.max(1,Math.ceil(actions.length/3));let one=[...sides,...actions.slice(0,split)],two=actions.slice(split),three=human;if(match==='wsl1025'){one=[3,4,2,...sides];two=[0,1,5,...actions.filter(i=>![0,1,2,3,4,5].includes(i))];}const fallback=entries.map(x=>x.i);if(!one.length)one=fallback.slice(0,3);if(!two.length)two=actions.length?actions:one;if(!three.length)three=sides.length?sides:fallback.slice(-3);const groups=[one,two,three];stops.forEach((s,i)=>{s.photos=[...new Set(groups[i])];s.selected=s.photos.includes(current)?current:s.photos[0];});const hasStands=entries.some(x=>x.p.category==='stands');stops[2].name=hasStands?'转向看台':'场边与故事';document.querySelector('[data-station="2"]').textContent=stops[2].name;const info=MATCHES.find(m=>m.id===match);q('#sceneMatch').textContent=info.date+' / '+info.label;}
